  "scene": "privacy-quiet-grid",
  "eyebrow": "Block · faq",
  "title": "Questions about blocks.",
  "openFirst": true,
  "items": [
    {
      "q": "Can a block hold another block?",
      "a": [
        "No. Blocks sit one after another. A signature block can host a richer composition of its own, but blocks do not nest."
      ]
    },
    {
      "q": "What ends a page?",
      "a": [
        "A closer. Every page except the contact page and the site map finishes with its own composition, and no two pages share one. None of them is a call to action."
      ]
    },
    {
      "q": "What is a signature?",
      "a": [
        "A composition that belongs to one page: a find bar for a long document, a tool, a demonstration. It is loaded when the page needs it, and it holds its height while it loads so that nothing jumps."
      ]
    },
    {
      "q": "How do I add a new kind of block?",
      "a": [
        "Write a component in the blocks folder, add one line to the block list so the loader knows its type, and add it to the catalogue on this page. If it brings keys that are not prose, add them to the search engine’s skip list."
      ]
    },
    {
      "q": "Is the text in the component or in the data?",
      "a": [
        "In the data. A component decides how things look and move; the words belong to the page."
      ]
    }
  ]
}

